def solution(n, k, moves):
    # After every move, scan the WHOLE board for k in a row.
    # O(n^2 * k) per move: fine for 3 x 3, far too slow for 150 x 150.
    board = [['.'] * n for _ in range(n)]
    for i in range(len(moves)):
        r, c = moves[i]
        board[r][c] = 'X' if i % 2 == 0 else 'O'
        for rr in range(n):
            for cc in range(n):
                m = board[rr][cc]
                if m == '.':
                    continue
                for dr, dc in ((0, 1), (1, 0), (1, 1), (1, -1)):
                    er, ec = rr + dr * (k - 1), cc + dc * (k - 1)
                    if not (0 <= er < n and 0 <= ec < n):
                        continue
                    if all(board[rr + dr * t][cc + dc * t] == m for t in range(k)):
                        return m
    if len(moves) == n * n:
        return 'Draw'
    return 'Pending'
